const faceDown=`<rect x="-26" y="-34" width="52" height="68" rx="10" fill="var(--brand)"/><rect x="-26" y="-34" width="52" height="68" rx="10" fill="url(#hatch)" opacity=".25"/><text y="8" text-anchor="middle" font-size="20" font-weight="800" fill="#fff" opacity=".75" font-family="var(--font)">b.</text>`;
